oxy_webhelp_navlinks = {"tocId-d39536e41705":{"topics":[{"title":"Azure DevOps","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> protects the data and resources of Azure DevOps projects,         repositories, and Developer Collaboration tools within the Azure DevOps         organization.<\/p>","href":"azure_devops\/azr_devops.html","attributes":{"data-id":"azr_devops"},"menu":{"hasChildren":false},"tocID":"azr_devops-d39536e41706","topics":[]},{"title":"Introduction to Azure DevOps","href":"azure_devops\/azr_devops_protection_key_features.html","menu":{"hasChildren":false},"tocID":"tocId-d39536e41719","next":"tocId-d39536e41719"},{"title":"High-level implementation workflow for Azure DevOps","shortdesc":"<p class=\"shortdesc\">The Azure DevOps protection implementation workflow involves a structured approach to         secure data management, starting with planning and preparation, followed by Azure DevOps         organization setup, Azure DevOps protection, continuous management and optimization, and         repository recovery.<\/p>","href":"azure_devops\/azr_devops_high_level_implement_workflow.html","attributes":{"data-id":"azr_devops_high_level_implement_workflow"},"menu":{"hasChildren":false},"tocID":"azr_devops_high_level_implement_workflow-d39536e41781","topics":[]},{"title":"Quick links for Azure DevOps","shortdesc":"<p class=\"shortdesc\">Immediate access to important tasks and information, enabling quick setup, daily         operations, and critical recovery.<\/p>","href":"azure_devops\/azr_devops_quick_links.html","attributes":{"data-id":"azr_devops_quick_links"},"menu":{"hasChildren":false},"tocID":"azr_devops_quick_links-d39536e41792","topics":[]},{"title":"Plan your Azure DevOps protection","shortdesc":"<p class=\"shortdesc\">Before setting up an Azure DevOps organization in <span class=\"ph\">RSC<\/span>, you are         required to plan the user and access management for designated <span class=\"ph\">RSC<\/span> users.         This planning also involves reviewing the permissions that <span class=\"ph\">RSC<\/span> requires in         your Azure environment to protect your Azure DevOps organizations.<\/p>","href":"azure_devops\/azr_devops_plan_protection.html","attributes":{"data-id":"azr_devops_plan_protection"},"menu":{"hasChildren":false},"tocID":"azr_devops_plan_protection-d39536e41803","next":"azr_devops_plan_protection-d39536e41803"},{"title":"Add Azure DevOps organizations to <span class=\"ph\">RSC<\/span>","shortdesc":"<p class=\"shortdesc\">Adding Azure DevOps organizations to <span class=\"ph\">RSC<\/span> involves completing         prerequisite planning tasks and choosing an onboarding method that fits the authentication         model and infrastructure requirements of your organization.<\/p>","href":"azure_devops\/azr_devops_add_orgs.html","attributes":{"data-id":"azr_devops_add_orgs"},"menu":{"hasChildren":false},"tocID":"azr_devops_add_orgs-d39536e41880","topics":[]},{"title":"Evaluate Azure DevOps setup options","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides three methods for adding Azure DevOps organizations:         Configure with OAuth, Configure without OAuth, and Rubrik-hosted Exocompute. Compare these         methods to choose the approach that best fits the authentication requirements of your         organization, infrastructure model, and onboarding scale.<\/p>","href":"azure_devops\/azr_devops_evaluate_setup_options.html","attributes":{"data-id":"azr_devops_evaluate_setup_options"},"menu":{"hasChildren":false},"tocID":"azr_devops_evaluate_setup_options-d39536e41896","topics":[]},{"title":"Permission categories for Azure DevOps","shortdesc":"<p class=\"shortdesc\">For the backup and recovery tasks associated with Azure DevOps organizations,         projects, and repositories, <span class=\"ph\">RSC<\/span> requires specific permissions. <span class=\"ph\">RSC<\/span> groups these permissions into categories for granular management so that         you can include or exclude these categories as required.<\/p>","href":"azure_devops\/azr_devops_permission_categories.html","attributes":{"data-id":"azr_devops_permission_categories"},"menu":{"hasChildren":false},"tocID":"azr_devops_permission_categories-d39536e41909","next":"azr_devops_permission_categories-d39536e41909"},{"title":"Set up Exocompute for Azure DevOps","shortdesc":"<p class=\"shortdesc\">With the Exocompute on Azure feature, <span class=\"ph\">RSC<\/span> launches an Azure         Kubernetes Service cluster to perform backup and recovery  operations to protect Azure         DevOps organizations. <span class=\"ph\">RSC<\/span> uses the Azure Kubernetes Service cluster to serve         as a compute resource in your Azure DevOps organization.<\/p>","href":"azure_devops\/azr_devops_set_up_exocompute.html","attributes":{"data-id":"azr_devops_set_up_exocompute"},"menu":{"hasChildren":false},"tocID":"azr_devops_set_up_exocompute-d39536e41950","topics":[]},{"title":"Set up backup location for Azure DevOps","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> protects your Azure DevOps organizations, projects, and         repositories. You can set up a backup location in Azure for storing the snapshots of Azure         DevOps organizations, projects, and repositories.<\/p>","href":"azure_devops\/azr_devops_set_up_backup_loc.html","attributes":{"data-id":"azr_devops_set_up_backup_loc"},"menu":{"hasChildren":false},"tocID":"azr_devops_set_up_backup_loc-d39536e41967","next":"azr_devops_set_up_backup_loc-d39536e41967"},{"title":"Adding Azure DevOps organizations with OAuth","shortdesc":"<p class=\"shortdesc\">Add one or more Azure DevOps organizations to <span class=\"ph\">RSC<\/span> using the Configure         with OAuth method to protect repositories and enable backup and recovery.<\/p>","href":"azure_devops\/azure_devops_adding_orgs_oauth.html","attributes":{"data-id":"azure_devops_adding_orgs_oauth"},"menu":{"hasChildren":false},"tocID":"azure_devops_adding_orgs_oauth-d39536e42076","topics":[]},{"title":"Granting Basic access level in Azure DevOps","shortdesc":"<p class=\"shortdesc\">Grant Basic access level to a user in an Azure DevOps organization to enable         onboarding and protection operations with <span class=\"ph\">RSC<\/span>.<\/p>","href":"azure_devops\/azr_devops_granting_basic_access.html","attributes":{"data-id":"azr_devops_granting_basic_access"},"menu":{"hasChildren":false},"tocID":"azr_devops_granting_basic_access-d39536e42091","topics":[]},{"title":"Adding Azure DevOps organization without OAuth","shortdesc":"<p class=\"shortdesc\">Add an Azure DevOps organization to <span class=\"ph\">RSC<\/span> using the Configure without OAuth method to retain full         control over your Service Principal lifecycle and permission setup.<\/p>","href":"azure_devops\/azure_devops_adding_orgs_without_oauth.html","attributes":{"data-id":"azure_devops_adding_orgs_without_oauth"},"menu":{"hasChildren":false},"tocID":"azure_devops_adding_orgs_without_oauth-d39536e42105","topics":[]},{"title":"Adding Azure DevOps organization using Rubrik-hosted Exocompute","shortdesc":"<p class=\"shortdesc\">Add an Azure DevOps organization using rubrik-hosted Exocompute with <span class=\"ph\">RSC<\/span> to back up and recover repositories, manage organizations, and minimize         downtime.<\/p>","href":"azure_devops\/azure_devops_adding_orgs_rubrik_hosted.html","attributes":{"data-id":"azure_devops_adding_orgs_rubrik_hosted"},"menu":{"hasChildren":false},"tocID":"azure_devops_adding_orgs_rubrik_hosted-d39536e42119","topics":[]},{"title":"Manage Azure DevOps organization","href":"azure_devops\/azure_devops_edit_org.html","menu":{"hasChildren":false},"tocID":"tocId-d39536e42133","next":"tocId-d39536e42133"},{"title":"Set up protection for Azure DevOps","shortdesc":"<p class=\"shortdesc\">You can set up SLA Domains to apply data protection policies, ensuring automatic and         hierarchical protection of Azure DevOps organizations, projects, repositories, and Developer         Collaboration tools with granular control overriding higher-level assignments.<\/p>","href":"azure_devops\/azr_devops_set_up_protection.html","attributes":{"data-id":"azr_devops_set_up_protection"},"menu":{"hasChildren":false},"tocID":"azr_devops_set_up_protection-d39536e42173","topics":[]},{"title":"SLA Domain assignment hierarchy for Azure DevOps","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides hierarchy-based, automatic protection for Azure DevOps         organizations, simplifying the assignment of SLA domains across organizations, projects, and         repositories.<\/p>","href":"azure_devops\/azr_devops_sla_assignment_hierarchy.html","attributes":{"data-id":"azr_devops_sla_assignment_hierarchy"},"menu":{"hasChildren":false},"tocID":"azr_devops_sla_assignment_hierarchy-d39536e42184","topics":[]},{"title":"Best practices for Azure DevOps SLA Domain assignment","shortdesc":"<p class=\"shortdesc\">Information about the best practices for assigning SLA Domains to Azure DevOps         organizations, ensuring effective data protection and compliance.<\/p>","href":"azure_devops\/azr_devops_best_practices_sla_assign.html","attributes":{"data-id":"azr_devops_best_practices_sla_assign"},"menu":{"hasChildren":false},"tocID":"azr_devops_best_practices_sla_assign-d39536e42197","topics":[]},{"title":"Evaluate Azure DevOps protection options","shortdesc":"<p class=\"shortdesc\">Understanding the various protection options is important when creating an SLA Domain         for your Azure DevOps organization. This ensures alignment with organizational needs.         Thoroughly evaluating these options enables making informed decisions and providing         effective protection for the workloads.<\/p>","href":"azure_devops\/azr_devops_evaluate_protection_options.html","attributes":{"data-id":"azr_devops_evaluate_protection_options"},"menu":{"hasChildren":false},"tocID":"azr_devops_evaluate_protection_options-d39536e42208","next":"azr_devops_evaluate_protection_options-d39536e42208"},{"title":"Configure Azure DevOps protection","shortdesc":"<p class=\"shortdesc\">After you have decided on the protection policies you want to configure, you can         begin the protection setup by creating an SLA Domain and assigning protection to Azure         DevOps organizations, projects, and repositories.<\/p>","href":"azure_devops\/azr_devops_configure_protection.html","attributes":{"data-id":"azr_devops_configure_protection"},"menu":{"hasChildren":false},"tocID":"azr_devops_configure_protection-d39536e42244","next":"azr_devops_configure_protection-d39536e42244"},{"title":"Manage Azure DevOps organizations","shortdesc":"<p class=\"shortdesc\">After completing the protection setup for Azure DevOps organizations, projects, and         repos, <span class=\"ph\">RSC<\/span> takes automated snapshots of those repos based on the configured         policies in SLA Domains. You can also take on-demand snapshots and refresh Azure DevOps         organizations for better resource management.<\/p>","href":"azure_devops\/azr_devops_manage_organizations.html","attributes":{"data-id":"azr_devops_manage_organizations"},"menu":{"hasChildren":false},"tocID":"azr_devops_manage_organizations-d39536e42299","next":"azr_devops_manage_organizations-d39536e42299"},{"title":"Recover Azure DevOps","shortdesc":"<p class=\"shortdesc\">After <span class=\"ph\">RSC<\/span> takes snapshots of your Azure DevOps repositories and         Developer Collaboration tools, you can recover them using individual repository recovery or         one-stop project recovery.<\/p>","href":"azure_devops\/azr_devops_recover.html","attributes":{"data-id":"azr_devops_recover"},"menu":{"hasChildren":false},"tocID":"azr_devops_recover-d39536e42384","topics":[]},{"title":"Privilege elevation for Azure DevOps recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> enhances the security of your Azure DevOps environment by         employing a least privilege model that limits the access granted to the minimal necessary         roles and resources for both repository and Developer Collaboration recovery.<\/p>","href":"azure_devops\/azr_devops_privilege_elevation.html","attributes":{"data-id":"azr_devops_privilege_elevation"},"menu":{"hasChildren":false},"tocID":"azr_devops_privilege_elevation-d39536e42399","topics":[]},{"title":"Azure DevOps repository settings backup and recovery","shortdesc":"<p class=\"shortdesc\">In addition to repository contents, <span class=\"ph\">RSC<\/span> backs up a set of Azure         DevOps repository-level settings and the branch policies of the repository as part of every         repository snapshot. During recovery, <span class=\"ph\">RSC<\/span> re-applies the settings and         recreates the branch policies on the destination repository.<\/p>","href":"azure_devops\/azr_devops_settings_backup_recovery.html","attributes":{"data-id":"azr_devops_settings_backup_recovery"},"menu":{"hasChildren":false},"tocID":"azr_devops_settings_backup_recovery-d39536e42412","topics":[]},{"title":"Evaluate Azure DevOps recovery options","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides two options for recovering Azure DevOps repositories:         individual repository recovery and project-level bulk recovery. Compare these options to         choose the approach that best fits the scope and requirements of your recovery         scenario.<\/p>","href":"azure_devops\/azr_devops_evaluate_recovery_options.html","attributes":{"data-id":"azr_devops_evaluate_recovery_options"},"menu":{"hasChildren":false},"tocID":"azr_devops_evaluate_recovery_options-d39536e42429","next":"azr_devops_evaluate_recovery_options-d39536e42429"},{"title":"Recovering individual Azure DevOps repositories","shortdesc":"<p class=\"shortdesc\">Recover a single Azure DevOps repository from a protected snapshot.<\/p>","href":"azure_devops\/azr_devops_recovering_proj_repos.html","attributes":{"data-id":"azr_devops_recovering_proj_repos"},"menu":{"hasChildren":false},"tocID":"azr_devops_recovering_proj_repos-d39536e42453","topics":[]},{"title":"Recovering all repositories in an Azure DevOps project","shortdesc":"<p class=\"shortdesc\">Recover some or all repositories within an Azure DevOps project to a new target         project in a single bulk restore operation.<\/p>","href":"azure_devops\/azr_devops_recovering_project.html","attributes":{"data-id":"azr_devops_recovering_project"},"menu":{"hasChildren":false},"tocID":"azr_devops_recovering_project-d39536e42464","topics":[]},{"title":"Recovering a project","shortdesc":"<p class=\"shortdesc\">Recover an Azure DevOps project by restoring Developer Collaboration tools and         repositories into a new project within the same organization.<\/p>","href":"azure_devops\/azr_devops_recovering_dev_collab.html","attributes":{"data-id":"azr_devops_recovering_dev_collab"},"menu":{"hasChildren":false},"tocID":"azr_devops_recovering_dev_collab-d39536e42475","next":"azr_devops_recovering_dev_collab-d39536e42475"},{"title":"Access Azure DevOps reports","shortdesc":"<p class=\"shortdesc\">With <span class=\"ph\">RSC<\/span>, you can create and download reports based on templates to         monitor the protection status of your Azure DevOps organizations, projects, and         repositories.<\/p>","href":"azure_devops\/azr_devops_access_reports.html","attributes":{"data-id":"azr_devops_access_reports"},"menu":{"hasChildren":false},"tocID":"azr_devops_access_reports-d39536e42500","next":"azr_devops_access_reports-d39536e42500"}]}};